 20:         state: directory
 21:       delegate_to: localhost
 22:       run_once: true
 23:   gather_facts: false
 24: 
 25: - name: generate hostvars[myvars] for all hosts
 26:   hosts: all
 27:   gather_facts: false
 28:   tasks:
 29:     - name: 'set myvars'
 30:       set_fact:
 31:         myvars:
 32:           fqdn: "{{ inventory_hostname }}"
 33:           bmc_ip: "{{ ipmi }}"
 34:           bmc_mac: "{{ bmc }}"
 35:           boot_ip: "{{ hostvars[inventory_hostname][maas_boot_ip_var] }}"
 36:           boot_mac: "{{ hostvars[inventory_hostname][maas_boot_mac_var] }}"
 37:           domain: "{{ inventory_hostname | regex_replace('^[^.]+\\.', '') }}"
 38:           shortname: "{{ inventory_hostname | regex_replace('\\..*', '') }}"
 39:           # for tucson, ignore the last 4; for pok, the last 3
 40:           # maybe an algorithm: have a "top-level lab domain" var,
 41:           # ceph.tuc.ibm.com or sepia.ceph.com, and remove it, then sub
 42:           # . to -
 43:           # domain_tag: "{{ inventory_hostname.split('.')[1:-4] | join('-') }}"
 44:           domain_tag: "{{ inventory_hostname.split('.')[1:-3] | join('-') }}"
 45:       tags: always
 46: 
 47: 
 48: - name: generate files from hostvars[myvars]
 49:   hosts: all
 50:   gather_facts: false
 51:   vars:
 52:     ipmi_file: "../dnsmasq.conf/ipmi.conf"
 53:     ipmi_domain: "ipmi.ceph.tuc.ibm.com"
 54: 
 55:   tasks:
 56:     #- name: get myvars
 57:     #  set_fact:
 58:     #    myvars: "{{ hostvars[inventory_hostname].myvars }}"
 59: 
 60:     - name: build {{ ipmi_file }}
 61:       copy:
 62:         dest: "{{ ipmi_file }}"
 63:         content: |
 64:           ###
 65:           ### {{ ipmi_domain }}
 66:           ###
 67:           {% for host in ansible_play_hosts %}
 68:           {% set data = hostvars[host]['myvars'] %}
 69:           dhcp-host=set:ipmi,{{ data.bmc_mac }},{{ data.bmc_ip }},{{ data.shortname }}.{{ ipmi_domain }}
 70:           {% endfor %}
 71:           {% for host in ansible_play_hosts %}
 72:           {% set data = hostvars[host]['myvars'] %}
 73:           host-record={{ data.shortname }}.{{ ipmi_domain }},{{ data.bmc_ip }}
 74:           {% endfor %}
 75:           {% for vlan in maas_networking[0]['vlans'] %}
 76:           {% set data = hostvars[ansible_play_hosts[0]].myvars %}
 77:           {% for subnet in vlan['subnets'] %}
 78:           {% if data.bmc_ip | ansible.utils.ipaddr(subnet.cidr) %}
 79:           dhcp-range={{ subnet.gateway | ansible.utils.ipmath(5) }},static,{{ subnet.cidr | ansible.utils.ipaddr("netmask") }},{{ subnet.cidr | ansible.utils.ipaddr("broadcast") }}
 80:           dhcp-option=tag:ipmi,option:router,{{ subnet.gateway }}
 81:           {% endif %}
 82:           {% endfor %}
 83:           {% endfor %}
 84: 
 85:       delegate_to: localhost
 86:       run_once: true
 87:       tags: ipmi
 88: 
 89:     # create a map from domain_tag to a list of hosts, so that we can loop
 90:     # across all the domain_tags
 91:     - name: Build map of domain_tag →> list of hosts
 92:       set_fact:
 93:         hosts_by_domain_tag: >-
 94:           {{
 95:             hosts_by_domain_tag | default({}) | combine({
 96:               (hostvars[item]['myvars']['domain_tag']): (
 97:                 (hosts_by_domain_tag | default({})).get(hostvars[item]['myvars']['domain_tag'], []) + [item]
 98:               )
 99:             })
100:           }}
101:       loop: "{{ ansible_play_hosts }}"
102:       loop_control:
103:         loop_var: item
104:       delegate_to: localhost
105:       run_once: true
106: 
107:     # maas_networking variable:
108:     # maas_networking['tucson-qe']['vlans'][]['subnets'][]['cidr']
109: 
110:     # loop across hosts_by_domain_tag, create a file named with 'domain_tag',
111:     # add dhcp-host and host-record stanzas
112:     - name: "build domain_tag dnsmasq conf part files"
113:       copy:
114:         dest: "../dnsmasq.conf/{{ domain_tag | replace('-', '.') }}.conf"
115:         content: |
116:           {% set domain = domain_tag | replace('-', '.') + '.' + ipmi_domain %}
117:           ###
118:           ### {{ domain }}
119:           ###
120:           {% for host in hosts_by_domain_tag[domain_tag] %}
121:           {% set data = hostvars[host]['myvars'] %}
122:           dhcp-host=set:maas,set:{{domain_tag}},{{ data.boot_mac }},{{ data.boot_ip }},{{ data.fqdn }}
123:           {% endfor %}
124:           {% for host in hosts_by_domain_tag[domain_tag] %}
125:           {% set data = hostvars[host]['myvars'] %}
126:           host-record={{ data.fqdn }},{{ data.boot_ip }}
127:           {% endfor %}
128:           {% for vlan in maas_networking[0]['vlans'] %}
129:           {% for subnet in vlan['subnets'] %}
130:           {% if domain == subnet.domain %}
131:           dhcp-range={{ subnet.gateway | ansible.utils.ipmath(5) }},static,{{ subnet.cidr | ansible.utils.ipaddr("netmask") }},{{ subnet.cidr | ansible.utils.ipaddr("broadcast") }}
132:           dhcp-option=tag:{{ domain_tag }},option:router,{{ subnet.gateway }}
133:           {% endif %}
134:           {% endfor %}
135:           {% endfor %}
136:       loop: "{{ hosts_by_domain_tag.keys() }}"
137:       loop_control:
138:         loop_var: domain_tag
139:       delegate_to: localhost
140:       run_once: true
141: 
142:     - name: "build list of local= lines"
143:       copy:
144:         dest: "../dnsmasq.conf/local.conf"
145:         content: |
146:           local=/{{ ipmi_domain }}/
147:           {% for domain_tag in hosts_by_domain_tag.keys() %}
148:           {% set hv = hostvars[hosts_by_domain_tag[domain_tag][0]] %}
149:           ### from {{ hv['myvars'].fqdn }}
150:           local=/{{ hv['myvars'].domain }}/
151:           {% endfor %}
152:       delegate_to: localhost
153:       run_once: true

